=== FILE: tb/tb_mac8.v ===
// Self-checking testbench for mac8: scoreboard against a reference model
// written from interface_spec.md ([req:MAC-RESET], [req:MAC-CLEAR],
// [req:MAC-ACC], [req:MAC-HOLD], [req:MAC-SAT], [req:MAC-STICKY]),
// not from the RTL. Inputs are driven at the falling edge; outputs are
// compared 1 ns after the falling edge (no change allowed) and 1 ns after
// the rising edge (model update). Every compare counts as one check.
`timescale 1ns / 1ps
module tb_mac8;

    reg         clk;
    reg         rst_n;
    reg         clr;
    reg         en;
    reg  [7:0]  a;
    reg  [7:0]  b;
    wire [23:0] acc;
    wire        sat;

    mac8 dut (
        .clk   (clk),
        .rst_n (rst_n),
        .clr   (clr),
        .en    (en),
        .a     (a),
        .b     (b),
        .acc   (acc),
        .sat   (sat)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // ---------------- reference model state ----------------
    reg  [23:0] m_acc;
    reg         m_sat;
    reg         m_valid;   // becomes 1 at the first reset edge

    // ---------------- scoreboard bookkeeping ----------------
    integer n_pass;
    integer n_fail;
    integer n_shown;
    integer cycle;

    // corner counters: a clean pass means nothing for a corner never reached
    integer c_rst_with_en;
    integer c_rst_from_sat;
    integer c_clr_with_en;
    integer c_clr_from_sat;
    integer c_boundary_exact;
    integer c_sat_event;
    integer c_sticky_zero;
    integer c_sticky_en;
    integer c_sticky_hold;
    integer c_hold_nonzero;
    integer c_max_operands;
    integer c_unsigned_hi;

    reg  [31:0]      rng;
    reg  [31:0]      rbits;
    reg  [31:0]      obits;
    reg  [8*128-1:0] nonce;
    reg  [7:0]       ch;
    integer          have_nonce;
    integer          i;
    reg              r_rst, r_clr, r_en;
    reg  [7:0]       r_a, r_b;

    function [31:0] xorshift32;
        input [31:0] x;
        reg   [31:0] y;
        begin
            y = x ^ (x << 13);
            y = y ^ (y >> 17);
            y = y ^ (y << 5);
            xorshift32 = y;
        end
    endfunction

    // Reference model: one rising edge, from the specification text.
    task model_edge;
        input       r;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        reg   [31:0] product;
        reg   [31:0] total;
        begin
            product = {24'd0, ia} * {24'd0, ib};      // both unsigned
            if (r == 1'b0) begin                      // MAC-RESET
                if (e) c_rst_with_en = c_rst_with_en + 1;
                if (m_valid && m_sat) c_rst_from_sat = c_rst_from_sat + 1;
                m_acc   = 24'd0;
                m_sat   = 1'b0;
                m_valid = 1'b1;
            end else if (!m_valid) begin
                // before the first reset the state is unspecified
            end else if (c == 1'b1) begin             // MAC-CLEAR, wins over en
                if (e) c_clr_with_en = c_clr_with_en + 1;
                if (m_sat) c_clr_from_sat = c_clr_from_sat + 1;
                m_acc = 24'd0;
                m_sat = 1'b0;
            end else if (e == 1'b1) begin             // MAC-ACC
                if (ia == 8'hFF && ib == 8'hFF) c_max_operands = c_max_operands + 1;
                if ((ia[7] || ib[7]) && product != 0) c_unsigned_hi = c_unsigned_hi + 1;
                if (m_sat) c_sticky_en = c_sticky_en + 1;
                total = {8'd0, m_acc} + product;
                if (total > 32'h00FFFFFF) begin       // MAC-SAT
                    if (!m_sat) c_sat_event = c_sat_event + 1;
                    m_acc = 24'hFFFFFF;
                    m_sat = 1'b1;
                end else begin
                    if (total == 32'h00FFFFFF && !m_sat)
                        c_boundary_exact = c_boundary_exact + 1;
                    if (m_sat) c_sticky_zero = c_sticky_zero + 1;   // MAC-STICKY
                    m_acc = total[23:0];
                    // m_sat unchanged: sticky until clear or reset
                end
            end else begin                            // MAC-HOLD
                if (m_sat) c_sticky_hold = c_sticky_hold + 1;
                if (m_acc != 24'd0) c_hold_nonzero = c_hold_nonzero + 1;
            end
        end
    endtask

    // Scoreboard compare of every output against the model.
    task sb_compare;
        input [8*16-1:0] phase;
        begin
            if (m_valid) begin
                if (acc === m_acc && sat === m_sat) begin
                    n_pass = n_pass + 1;
                end else begin
                    n_fail = n_fail + 1;
                    if (n_shown < 10) begin
                        n_shown = n_shown + 1;
                        $display("MISMATCH cycle %0d %0s: rst_n=%b clr=%b en=%b a=%0d b=%0d | dut acc=%h sat=%b | model acc=%h sat=%b",
                                 cycle, phase, rst_n, clr, en, a, b, acc, sat, m_acc, m_sat);
                    end
                end
            end
        end
    endtask

    // One clock cycle: drive at the falling edge, check, edge, model, check.
    task drive_cycle;
        input       r;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        begin
            @(negedge clk);
            rst_n = r;
            clr   = c;
            en    = e;
            a     = ia;
            b     = ib;
            #1;
            sb_compare("before-edge");
            @(posedge clk);
            model_edge(r, c, e, ia, ib);
            #1;
            sb_compare("after-edge");
            cycle = cycle + 1;
        end
    endtask

    task corner;
        input [8*40-1:0] name;
        input integer    count;
        begin
            if (count > 0) begin
                n_pass = n_pass + 1;
                $display("CORNER %0s reached %0d times", name, count);
            end else begin
                n_fail = n_fail + 1;
                $display("CORNER %0s NOT reached: run says nothing about it", name);
            end
        end
    endtask

    initial begin
        rst_n = 1'b0; clr = 1'b0; en = 1'b0; a = 8'd0; b = 8'd0;
        m_acc = 24'd0; m_sat = 1'b0; m_valid = 1'b0;
        n_pass = 0; n_fail = 0; n_shown = 0; cycle = 0;
        c_rst_with_en = 0; c_rst_from_sat = 0; c_clr_with_en = 0; c_clr_from_sat = 0;
        c_boundary_exact = 0; c_sat_event = 0; c_sticky_zero = 0; c_sticky_en = 0;
        c_sticky_hold = 0; c_hold_nonzero = 0; c_max_operands = 0; c_unsigned_hi = 0;
        rng = 32'h1F2E_3D4C;
        nonce = 0;
        have_nonce = 0;
        if ($value$plusargs("nonce=%s", nonce)) have_nonce = 1;
        else if ($value$plusargs("NONCE=%s", nonce)) have_nonce = 1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce)) have_nonce = 1;
        else if ($value$plusargs("NIRMAAN_NONCE=%s", nonce)) have_nonce = 1;
        if (!have_nonce) $display("NOTE: no nonce plusarg found");

        // D1 MAC-RESET: reset wins over accumulate and clear
        drive_cycle(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive_cycle(1'b0, 1'b1, 1'b1, 8'hFF, 8'hFF);
        drive_cycle(1'b0, 1'b0, 1'b0, 8'h00, 8'h00);

        // D2 MAC-ACC: unsigned products, MSB-set operands
        drive_cycle(1'b1, 1'b0, 1'b1, 8'd3,  8'd5);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h80, 8'h01);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF, 8'h02);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h00, 8'hAB);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);

        // D3 MAC-HOLD: en low with operands present
        drive_cycle(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b0, 8'h12, 8'h34);
        drive_cycle(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);

        // D4 MAC-CLEAR: clear wins over an accumulate at the same edge
        drive_cycle(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'd7,  8'd9);
        drive_cycle(1'b1, 1'b1, 1'b0, 8'h00, 8'h00);

        // D5 exact landing on 0xFFFFFF: 258*65025 + 765 = 16777215, no saturation
        drive_cycle(1'b1, 1'b1, 1'b0, 8'h00, 8'h00);
        for (i = 0; i < 258; i = i + 1)
            drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF, 8'd3);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);
        drive_cycle(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);
        // MAC-SAT: saturate by one
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);

        // D6 MAC-STICKY: zero products and holds keep the flag at 1
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h00, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF, 8'h00);
        drive_cycle(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);

        // D7 clear from saturation with an accumulate offered
        drive_cycle(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'd2,  8'd3);

        // D8 saturate by overshoot, then reset from saturation with en high
        for (i = 0; i < 258; i = i + 1)
            drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF, 8'd4);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);
        drive_cycle(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);

        // R random phase: rare reset/clear, en mostly high, operands biased high
        for (i = 0; i < 6000; i = i + 1) begin
            rng   = xorshift32(rng);
            rbits = rng;
            rng   = xorshift32(rng);
            obits = rng;
            r_rst = (rbits[11:0] == 12'd0) ? 1'b0 : 1'b1;
            r_clr = (rbits[21:12] == 10'd0) ? 1'b1 : 1'b0;
            r_en  = (rbits[24:22] != 3'd0) ? 1'b1 : 1'b0;
            case (rbits[26:25])
                2'd0: begin r_a = obits[7:0];          r_b = obits[15:8];          end
                2'd1: begin r_a = 8'hFF;               r_b = 8'hFF;                end
                2'd2: begin r_a = {6'd0, obits[1:0]};  r_b = obits[15:8];          end
                default: begin r_a = obits[7:0] | 8'hC0; r_b = obits[15:8] | 8'hC0; end
            endcase
            drive_cycle(r_rst, r_clr, r_en, r_a, r_b);
        end

        // the run fails itself for any corner it never reached
        corner("reset with en high",            c_rst_with_en);
        corner("reset from saturated",          c_rst_from_sat);
        corner("clear with en high",            c_clr_with_en);
        corner("clear from saturated",          c_clr_from_sat);
        corner("exact 0xFFFFFF no saturation",  c_boundary_exact);
        corner("saturation event",              c_sat_event);
        corner("sticky across non-overflow acc", c_sticky_zero);
        corner("accumulate while saturated",    c_sticky_en);
        corner("hold while saturated",          c_sticky_hold);
        corner("hold with nonzero total",       c_hold_nonzero);
        corner("operands 0xFF x 0xFF",          c_max_operands);
        corner("MSB-set operand, nonzero prod", c_unsigned_hi);

        $write("NIRMAAN-SIM ");
        for (i = 127; i >= 0; i = i - 1) begin
            ch = nonce[i*8 +: 8];
            if (ch != 8'd0) $write("%c", ch);
        end
        $display(" %0d passed, %0d failed", n_pass, n_fail);
        $finish;
    end

endmodule
=== END FILE ===
